    "name": "tokens-theme",
    "source": "import { css, defineTokens } from \"@kirana-style/core\"\n\n// A variable token: a typed constant here, a custom property in the CSS.\nconst brand = defineTokens(\n  \"demo-brand\",\n  { accent: \"light-dark(oklch(0.55 0.2 260), oklch(0.72 0.15 260))\" },\n  { variable: true }\n)\n\nconst styles = {\n  row: css({ display: \"flex\", alignItems: \"center\", gap: \"0.75rem\" }),\n  // A subtree overrides the value; everything below follows.\n  warm: css({\n    display: \"flex\",\n    [brand.accent]: \"light-dark(oklch(0.62 0.19 45), oklch(0.75 0.15 60))\",\n  }),\n  chip: css({\n    borderRadius: \"999px\",\n    paddingInline: \"0.875rem\",\n    paddingBlock: \"0.375rem\",\n    fontSize: \"0.875rem\",\n    fontWeight: 500,\n    color: \"white\",\n    backgroundColor: brand.accent,\n  }),\n}\n\nexport default function TokensTheme() {\n  return (\n    <div sx={styles.row}>\n      <span sx={styles.chip}>Default</span>\n      <div sx={styles.warm}>\n        <span sx={styles.chip}>Overridden</span>\n      </div>\n    </div>\n  )\n}\n",
    "sourceHtml": "<span class=\"th-token th-keyword\">import</span> { css, defineTokens } <span class=\"th-token th-keyword\">from</span> <span class=\"th-token th-string\">&quot;@kirana-style/core&quot;</span>\n\n<span class=\"th-token th-comment\">// A variable token: a typed constant here, a custom property in the CSS.</span>\n<span class=\"th-token th-keyword\">const</span> brand = <span class=\"th-token th-function\">defineTokens</span>(\n  <span class=\"th-token th-string\">&quot;demo-brand&quot;</span>,\n  { <span class=\"th-token th-property\">accent</span>: <span class=\"th-token th-string\">&quot;light-dark(oklch(0.55 0.2 260), oklch(0.72 0.15 260))&quot;</span> },\n  { <span class=\"th-token th-property\">variable</span>: <span class=\"th-token th-literal\">true</span> }\n)\n\n<span class=\"th-token th-keyword\">const</span> styles = {\n  <span class=\"th-token th-property\">row</span>: <span class=\"th-token th-function\">css</span>({ <span class=\"th-token th-property\">display</span>: <span class=\"th-token th-string\">&quot;flex&quot;</span>, <span class=\"th-token th-property\">alignItems</span>: <span class=\"th-token th-string\">&quot;center&quot;</span>, <span class=\"th-token th-property\">gap</span>: <span class=\"th-token th-string\">&quot;0.75rem&quot;</span> }),\n  <span class=\"th-token th-comment\">// A subtree overrides the value; everything below follows.</span>\n  <span class=\"th-token th-property\">warm</span>: <span class=\"th-token th-function\">css</span>({\n    <span class=\"th-token th-property\">display</span>: <span class=\"th-token th-string\">&quot;flex&quot;</span>,\n    [brand.<span class=\"th-token th-property\">accent</span>]: <span class=\"th-token th-string\">&quot;light-dark(oklch(0.62 0.19 45), oklch(0.75 0.15 60))&quot;</span>,\n  }),\n  <span class=\"th-token th-property\">chip</span>: <span class=\"th-token th-function\">css</span>({\n    <span class=\"th-token th-property\">borderRadius</span>: <span class=\"th-token th-string\">&quot;999px&quot;</span>,\n    <span class=\"th-token th-property\">paddingInline</span>: <span class=\"th-token th-string\">&quot;0.875rem&quot;</span>,\n    <span class=\"th-token th-property\">paddingBlock</span>: <span class=\"th-token th-string\">&quot;0.375rem&quot;</span>,\n    <span class=\"th-token th-property\">fontSize</span>: <span class=\"th-token th-string\">&quot;0.875rem&quot;</span>,\n    <span class=\"th-token th-property\">fontWeight</span>: <span class=\"th-token th-number\">500</span>,\n    <span class=\"th-token th-property\">color</span>: <span class=\"th-token th-string\">&quot;white&quot;</span>,\n    <span class=\"th-token th-property\">backgroundColor</span>: brand.<span class=\"th-token th-property\">accent</span>,\n  }),\n}\n\n<span class=\"th-token th-keyword\">export</span> <span class=\"th-token th-keyword\">default</span> <span class=\"th-token th-keyword\">function</span> <span class=\"th-token th-function\">TokensTheme</span>() {\n  <span class=\"th-token th-keyword\">return</span> (\n    &lt;<span class=\"th-token th-tag\">div</span> <span class=\"th-token th-attr\">sx</span>={styles.<span class=\"th-token th-property\">row</span>}&gt;\n      &lt;<span class=\"th-token th-tag\">span</span> <span class=\"th-token th-attr\">sx</span>={styles.<span class=\"th-token th-property\">chip</span>}&gt;Default&lt;/<span class=\"th-token th-tag\">span</span>&gt;\n      &lt;<span class=\"th-token th-tag\">div</span> <span class=\"th-token th-attr\">sx</span>={styles.<span class=\"th-token th-property\">warm</span>}&gt;\n        &lt;<span class=\"th-token th-tag\">span</span> <span class=\"th-token th-attr\">sx</span>={styles.<span class=\"th-token th-property\">chip</span>}&gt;Overridden&lt;/<span class=\"th-token th-tag\">span</span>&gt;\n      &lt;/<span class=\"th-token th-tag\">div</span>&gt;\n    &lt;/<span class=\"th-token th-tag\">div</span>&gt;\n  )\n}\n",
